frappe.ui.form.on('Frontline Incentive', {
    agency_contract: function(frm) {
        if (frm.doc.agency_contract) {
            frappe.db.get_doc('Agency Contract', frm.doc.agency_contract)
            .then(function(contract) {
                frm.set_value('agency_name', contract.agency_name);
                frm.set_value('account_manager', contract.account_manager);
            });
        }
    },
    total_segments: function(frm) {
        calculate_total(frm);
    },
    rate: function(frm) {
        calculate_total(frm);
    }
});

function calculate_total(frm) {
    if (frm.doc.total_segments && frm.doc.rate) {
        frm.set_value('total_usd', frm.doc.total_segments * frm.doc.rate);
    }
}

frappe.ui.form.on('Zoho Import', {

    refresh(frm) {

        // ── زر Process Import ─────────────────────────────────────
        if ((frm.doc.import_file || frm.doc.midt_file || frm.doc.sabre_file) && frm.doc.status !== 'Processing') {
            frm.add_custom_button(__('⚙️ Process Import'), () => {

                frappe.confirm(
                    __('سيقوم هذا الإجراء بقراءة الملف المرفق وإنشاء/تحديث سجلات Agency. هل تريد المتابعة؟'),
                    () => {
                        frappe.call({
                            method: 'sabre_finance.sabre_finance.api.process_zoho_import',
                            args:   { docname: frm.doc.name },
                            freeze: true,
                            freeze_message: __('⏳ جاري معالجة الملف، الرجاء الانتظار...'),
                            callback(r) {
                                if (r.message && r.message.status === 'success') {
                                    const m = r.message;
                                    frappe.msgprint({
                                        title:     __('✅ اكتملت عملية الاستيراد'),
                                        indicator: m.errors > 0 ? 'orange' : 'green',
                                        message: `
                                            <table class="table table-bordered" style="margin-top:8px">
                                                <tr><td><b>الصفوف المعالجة</b></td><td>${m.imported}</td></tr>
                                                <tr><td><b>وكالات جديدة</b></td><td>${m.new}</td></tr>
                                                <tr><td><b>سجلات محدّثة</b></td><td>${m.updated}</td></tr>
                                                <tr><td><b>صفوف متخطاة</b></td><td>${m.skipped}</td></tr>
                                                <tr><td><b>أخطاء</b></td><td>${m.errors}</td></tr>
                                            </table>
                                        `,
                                    });
                                    frm.reload_doc();
                                }
                            },
                        });
                    }
                );
            }, __('Actions'));
        }

        // ── لون مؤشر الحالة ──────────────────────────────────────
        const colors = {
            'Draft':                  'gray',
            'Processing':             'orange',
            'Completed':              'green',
            'Completed with Errors':  'yellow',
            'Failed':                 'red',
        };
        if (frm.doc.status) {
            frm.page.set_indicator(frm.doc.status, colors[frm.doc.status] || 'blue');
        }
    },

    // ── إعادة تهيئة الحقول عند إرفاق ملف جديد ──────────────────
    import_file(frm) {
        frm.set_value('status',        'Draft');
        frm.set_value('imported_rows', 0);
        frm.set_value('new_agencies',  0);
        frm.set_value('error_log',     '');
        frm.save();
    },
});

frappe.ui.form.on('Agency Contract', {
    refresh: function(frm) {
        // 1. كود الصلاحيات السابق
        if (frappe.user_roles.includes('Sabre Finance Manager') && !frappe.user_roles.includes('System Manager')) {
            let read_only_fields = [
                'pcc_code', 'agency_name', 'email', 'iata_number',
                'contract', 'account_manager', 'start_date', 'end_date',
                'payment_cycle'
            ];
            
            read_only_fields.forEach(function(field) {
                frm.set_df_property(field, 'read_only', 1);
            });
            
            frm.set_df_property('tiers', 'cannot_add_rows', true);
            frm.set_df_property('tiers', 'cannot_delete_rows', true);
        }

        // قفل حقول الحسابات التلقائية لضمان عدم التعديل اليدوي عليها
        frm.set_df_property('term_months', 'read_only', 1);
        frm.set_df_property('due_date', 'read_only', 1);
    },

    // عند تغيير تاريخ البداية
    start_date: function(frm) {
        calculate_all(frm);
    },

    // عند تغيير تاريخ النهاية
    end_date: function(frm) {
        calculate_all(frm);
    },

    // عند تغيير دورة الدفع
    payment_cycle: function(frm) {
        calculate_all(frm);
    }
});

// دالة تجميعية لضمان تنفيذ الحسابات بالترتيب الصحيح
function calculate_all(frm) {
    calculate_term_months(frm);
    calculate_due_date(frm);
    generate_payment_schedule(frm);
}

// 1. دالة حساب الأشهر (term_months)
function calculate_term_months(frm) {
    if (frm.doc.start_date && frm.doc.end_date) {
        let start = moment(frm.doc.start_date);
        let end = moment(frm.doc.end_date);
        let months = end.diff(start, 'months');
        frm.set_value('term_months', months >= 0 ? months : 0);
    } else {
        frm.set_value('term_months', 0);
    }
}

// 2. دالة حساب تاريخ الاستحقاق الأول الرئيسي (due_date)
function calculate_due_date(frm) {
    if (frm.doc.start_date && frm.doc.payment_cycle) {
        let days_to_add = 0;
        if (frm.doc.payment_cycle === 'Yearly') { days_to_add = 366; }
        else if (frm.doc.payment_cycle === 'Half Yearly') { days_to_add = 185; }
        else if (frm.doc.payment_cycle === 'Quarterly') { days_to_add = 95; }
        
        if (days_to_add > 0) {
            let calculated_due_date = moment(frm.doc.start_date).add(days_to_add, 'days').format('YYYY-MM-DD');
            frm.set_value('due_date', calculated_due_date);
        } else {
            frm.set_value('due_date', '');
        }
    } else {
        frm.set_value('due_date', '');
    }
}

// 3. دالة توليد جدول الدفعات ديناميكياً وحساب الـ 75 يوماً إضافية
function generate_payment_schedule(frm) {
    // تنظيف الجدول القديم لمنع تكرار البيانات عند كل تعديل
    frm.clear_table('payments');

    if (frm.doc.start_date && frm.doc.end_date && frm.doc.payment_cycle && frm.doc.term_months) {
        let total_months = parseInt(frm.doc.term_months) || 0;
        let months_per_cycle = 0;
        let days_per_cycle = 0;

        // تحديد مدة الدورة بالأشهر والأيام
        if (frm.doc.payment_cycle === 'Yearly') {
            months_per_cycle = 12;
            days_per_cycle = 366;
        } else if (frm.doc.payment_cycle === 'Half Yearly') {
            months_per_cycle = 6;
            days_per_cycle = 185;
        } else if (frm.doc.payment_cycle === 'Quarterly') {
            months_per_cycle = 3;
            days_per_cycle = 95;
        }

        if (months_per_cycle > 0 && total_months >= months_per_cycle) {
            // حساب عدد الدفعات الإجمالي (مثلاً: 60 شهر / 12 شهر = 5 دفعات)
            let num_payments = Math.floor(total_months / months_per_cycle);

            for (let i = 0; i < num_payments; i++) {
                // تاريخ بداية الدورة الحالية
                let current_period_start = moment(frm.doc.start_date).add(i * months_per_cycle, 'months');
                
                // تاريخ استحقاق الدورة الحالية (التاريخ الأساسي للدورة)
                let current_cycle_due = moment(current_period_start).add(days_per_cycle, 'days');
                
                // حساب تاريخ الدفع الفعلي (بإضافة 75 يوماً على تاريخ استحقاق الدورة)
                let final_payment_due_date = moment(current_cycle_due).add(75, 'days');

                // إضافة صف جديد للجدول الفرعي
                let row = frm.add_child('payments');
                row.payment_no = `Payment #${i + 1}`; // رقم الدفعة (تبدأ من 1)
                row.cycle_date = current_cycle_due.format('YYYY-MM-DD'); // تاريخ الدورة الأساسي
                row.payment_due_date = final_payment_due_date.format('YYYY-MM-DD'); // تاريخ الدفع المستحق (+75 يوم)
            }
        }
    }
    // تحديث الجدول على الشاشة فوراً ليراه المستخدم
    frm.refresh_field('payments');
}

