frappe.ui.form.on('Todd Report Import', {
    refresh(frm) {
        // نتحقق من وجود الملف (تأكد هل الحقل اسمه todd_file أو import_file في الـ DocType)
        const file_attached = frm.doc.todd_file || frm.doc.import_file;

        // ── 1. إضافة زر المعالجة ─────────────────────────────────
        if (file_attached && frm.doc.status !== 'Processing') {
            frm.add_custom_button(__('⚙️ Process Import'), () => {
                frappe.confirm(
                    __('سيقوم هذا الإجراء بقراءة ملف Todd وتخزين البيانات. هل تريد المتابعة؟'),
                    () => {
                        frappe.call({
                            method: 'sabre_finance.sabre_finance.todd_api.process_todd_import',
                            args: { docname: frm.doc.name },
                            freeze: true,
                            freeze_message: __('⏳ جاري استخراج البيانات...'),
                            callback(r) {
                                if (r.message && r.message.status === 'success') {
                                    frappe.msgprint({
                                        title: __('✅ اكتمل الاستيراد'),
                                        indicator: 'green',
                                        message: `تم استيراد ${r.message.imported} صف بنجاح.`
                                    });
                                    frm.reload_doc();
                                }
                            }
                        });
                    }
                );
            }, __('Actions'));
        }

        // ── 2. مؤشر حالة المستند ─────────────────────────────────
        const colors = {
            'Draft': 'gray',
            'Processing': 'orange',
            'Completed': 'green',
            'Failed': 'red',
        };
        if (frm.doc.status) {
            frm.page.set_indicator(frm.doc.status, colors[frm.doc.status] || 'blue');
        }
    },

    // ── 3. حدث حفظ المستند تلقائياً فور رفع الملف لإظهار الزر ──────
    todd_file(frm) {
        if (frm.doc.todd_file) {
            frm.set_value('status', 'Draft');
            frm.save();
        }
    },

    import_file(frm) {
        if (frm.doc.import_file) {
            frm.set_value('status', 'Draft');
            frm.save();
        }
    }
});

